    def _mifi_ctl(action):
        # MiFi mode: wlan0 AP sharing the cellular uplink, driven by the
        # DeadEye hostapd/dnsmasq switcher. FPMS runs as root -> no sudo.
        import os, subprocess
        from fpms.modules.pages.alert import Alert
        if g_vars["result_cache"] == True:
            g_vars["disable_keys"] = False
            return
        g_vars["drawing_in_progress"] = True
        g_vars["disable_keys"] = True
        alert = Alert(g_vars)
        switcher = "/opt/wlanpi-grafana/mifi/mifi-deadeye.sh"
        if not os.path.exists(switcher):
            alert.display_alert_info(g_vars, "Use Modes > MiFi on this platform.", title="MiFi")
        else:
            alert.display_popup_alert(g_vars, "MiFi " + action + "...")
            try:
                r = subprocess.run(switcher + " " + action, shell=True,
                                   capture_output=True, text=True, timeout=45)
                out = (r.stdout or "") + (r.stderr or "")
                if action == "on":
                    ssid = psk = ""
                    for line in out.splitlines():
                        s = line.strip()
                        if s.startswith("SSID:"):
                            ssid = s.split(":", 1)[1].strip()
                        elif s.startswith("PSK:"):
                            psk = s.split(":", 1)[1].strip()
                    if ssid:
                        alert.display_alert_info(g_vars, "SSID: %s  PW: %s" % (ssid, psk), title="MiFi On")
                    else:
                        alert.display_alert_error(g_vars, "MiFi start failed.")
                elif action == "off":
                    alert.display_alert_info(g_vars, "MiFi is off.", title="MiFi")
                else:
                    state = "on" if "state: mifi" in out else "off"
                    alert.display_alert_info(g_vars, "MiFi is " + state + ".", title="MiFi")
            except Exception:
                alert.display_alert_error(g_vars, "MiFi command failed.")
        g_vars["result_cache"] = True
        g_vars["display_state"] = "page"
        g_vars["drawing_in_progress"] = False

